"""Compare the layout-F parts regenerated by build_f.py (hidden cap screw, no P1) with the hidden-option study meshes
(options/{frame,lid}_hidden-world.stl, made by boolean edits of the V1.14 release meshes). Reports volumes, the
symmetric-difference volume and the largest surface-to-surface distance (vertices of each mesh to the other surface).
Writes compare_regenerated.json.

    /tmp/microduck-cad-venv/bin/python compare_regenerated.py"""
import json
from pathlib import Path
import numpy as np, trimesh, manifold3d as m3d
HERE = Path(__file__).resolve().parent; LF = HERE.parent / 'layout-F'
def man(t):
    return m3d.Manifold(m3d.Mesh(vert_properties=np.asarray(t.vertices, np.float32), tri_verts=np.asarray(t.faces, np.uint32)))
def load(p):
    t = trimesh.load(str(p), force='mesh'); t.merge_vertices(); return t
def far(a, b, n=60000):
    pts = a.vertices if len(a.vertices) <= n else a.vertices[np.random.default_rng(0).choice(len(a.vertices), n, replace=False)]
    _, d, _ = trimesh.proximity.closest_point(b, pts); i = int(np.argmax(d))
    return float(d[i]), np.round(pts[i], 2).tolist()
out = {}
for nm, gen in (('frame', 'rear_frame-world.stl'), ('lid', 'rear_lid-world.stl')):
    g, h = load(LF / gen), load(HERE / f'options/{nm}_hidden-world.stl')
    mg, mh = man(g), man(h)
    d1, p1 = far(g, h); d2, p2 = far(h, g)
    out[nm] = dict(regenerated=str(LF / gen), study=str(HERE / f'options/{nm}_hidden-world.stl'),
                   volumeRegeneratedMm3=round(float(g.volume), 1), volumeStudyMm3=round(float(h.volume), 1),
                   volumeDifferenceMm3=round(float(g.volume - h.volume), 1),
                   onlyInRegeneratedMm3=round((mg - mh).volume(), 1), onlyInStudyMm3=round((mh - mg).volume(), 1),
                   maxDistanceRegeneratedToStudyMm=round(d1, 3), at=p1, maxDistanceStudyToRegeneratedMm=round(d2, 3), at2=p2)
    print(nm, out[nm])
(HERE / 'compare_regenerated.json').write_text(json.dumps(out, indent=1) + '\n')
